def find_path(grid, start, end):
    rows = len(grid)
    cols = len(grid[0])
    def dfs(r, c, path):
        if (r, c) == end:
            return path + [(r, c)]
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == 1:
            return None
        path.append((r, c))
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            result = dfs(r + dr, c + dc, path)
            if result is not None:
                return result
        path.pop()
        return None
    return dfs(start[0], start[1], [])

