def can_schedule(tasks, current):
    visited = set()
    def dfs(node):
        if node in visited:
            return False
        visited.add(node)
        for neighbor in tasks.get(node, []):
            if not dfs(neighbor):
                return False
        visited.remove(node)
        return True
    return dfs(current)

