def can_schedule(tasks, current):
    visited = set()
    def dfs(node):
        if node in visited:
            print('Cycle detected at', node)
            return False
        visited.add(node)
        print('Push', node)
        for neighbor in tasks.get(node, []):
            if not dfs(neighbor):
                return False
        visited.remove(node)
        print('Pop', node)
        return True
    return dfs(current)

tasks = {
    'A': ['B'],
    'B': ['C'],
    'C': []
}
print(can_schedule(tasks, 'A'))

tasks_cycle = {
    'A': ['B'],
    'B': ['C'],
    'C': ['A']
}
print(can_schedule(tasks_cycle, 'A'))

