def explore(node, path):
    result = []
    def dfs(current, depth):
        indent = '  ' * depth
        print(indent + 'Entering', current.name)
        if current.is_file:
            result.append(path + '/' + current.name)
            print(indent + 'Leaf file:', current.name)
            return
        if current.is_symlink:
            print(indent + 'Skipping symlink:', current.name)
            return
        for child in current.children:
            dfs(child, depth + 1)
            print(indent + 'Backtrack from', child.name)
    dfs(node, 0)
    return result

class Node:
    def __init__(self, name, is_file=False, is_symlink=False, children=None):
        self.name = name
        self.is_file = is_file
        self.is_symlink = is_symlink
        self.children = children or []

root = Node('root', children=[
    Node('docs', children=[
        Node('report.txt', is_file=True),
        Node('link', is_symlink=True)
    ]),
    Node('images', children=[
        Node('photo.jpg', is_file=True)
    ])
])
print(explore(root, ''))

